a(1100,'<ffx:disgust_light>إذن أنت... نجوت أيها الوغد... <ffx:wonder_light>يحتاج المرء إلى مهارة حقيقية كي... يفلت من سيد الغابة... <ffx:fear_light>وهذا يعني... أنك... خطير...<ffx:neutral>')
a(1103,'<ffx:wonder>دافعت عن رفاقنا... لم أجبن... ولم أتنمر... على الفتيات... <ffx:smile>يا معلم، أنا هنا... آخ...<ffx:neutral>')
a(1104,'<ffx:anger_light>أسرع! لعل يفغيني <ffx:wonder>القرصان ما زال حيًا!<ffx:neutral>')
a(1106,'<ffx:wonder>وماذا تظن؟ <ffx:sadness>لقد تلقى ضربة من سيد الغابة...<ffx:neutral>','Master الدب، لا المعلم.')
a(1107,'<ffx:sadness>لعل سيد الغابة قتل يفغيني أيضًا... <ffx:wonder>ذهبتَ إلى المعسكر ثم جئنا إلى هنا؛ وقد استغرق هذا وقتًا...<ffx:neutral>')
a(1108,'<ffx:wonder>وماذا في ذلك؟ علينا <ffx:sadness_light>إعادة الجثث على الأقل... <ffx:sadness>سيصفوننا بالجبن إن لم نفعل...<ffx:neutral>')
a(1109,'<ffx:sadness>نعم... فلنسرع إذن...<ffx:neutral>')
a(1110,'<ffx:sadness>نعم... لكن أخبرني: <ffx:wonder>كيف لم تروا سيد الغابة؟<ffx:neutral>')
a(1111,'<ffx:sadness>إنه يتحرك بصمت... <ffx:anger>وكنا مشتتين؛ <ffx:wonder>فقد وقع دخيل آخر في الفخ، <ffx:disgust>وتحمس يفغيني وطالب بالغنيمة كلها، أو بالحذاء على الأقل...<ffx:neutral>')
a(1113,'<ffx:sadness_light>ما زال معلقًا هناك، إن لم <ffx:wonder>يفترسه سيد الغابة...<ffx:neutral>','المقصود معلق في فخ شبكي، لا التسكع.')
a(1115,'<ffx:wonder_light>نعم، فلنسرع الخطى...<ffx:neutral>')
a(1116,'<ffx:sadness_strong>يفغيني! تبًا... <ffx:sadness>لقد صار مع المعلم...<ffx:neutral>')
a(1117,'<ffx:sadness>تبًا... كدت تفلت من سيد الغابة... كدت...<ffx:neutral>')
a(1118,'<ffx:wonder_strong>انظر! سيد الغابة جرحه فقط! من أجهز عليه إنسان! <ffx:disgust_strong>إن صحّ أن نسميه إنسانًا...<ffx:neutral>')
a(1121,'<ffx:anger>نعم! لنقتل الوغد انتقامًا ليفغيني... <ffx:sadness>كان قرصانًا، لكنه ظل واحدًا منا... <ffx:disgust>أما الدخيل فقاطع طريق حقًا... <ffx:disgust_strong>يا لحقارته، يقتل الجرحى!<ffx:neutral>')
a(1122,'<ffx:sadness>إذن قضى عليه سيد الغابة... من المعجز أنه بلغ هذا المكان بجرح كهذا...<ffx:neutral>')
a(1124,'<ffx:sadness_light>افترسه سيد الغابة، ماذا غير ذلك... <ffx:smile_light>كان عالقًا في الفخ كقطعة لحم خنزير. <ffx:sadness>يا للخسارة، ذلك الحذاء...<ffx:neutral>')
a(1126,'<ffx:fear>لا! بالطبع يهمني رفاقنا... لكن... كان سيد الغابة... <ffx:sadness>ما زلت لا أصدق أنني أفلتّ منه...<ffx:neutral>')
a(1127,'<ffx:sadness>نعم... كُتب لك اليوم عمر جديد، وستكون لديك قصة رائعة ترويها...<ffx:neutral>')
a(1128,'<ffx:sadness>علينا حمل يفغيني وبيتر إلى المعسكر أولًا... <ffx:wonder_light>ثم نسلّم يفغيني للقراصنة...<ffx:neutral>')
a(1129,'<ffx:sadness>بالتأكيد. لكن لننتظر قليلًا، <ffx:fear>فسيد الغابة ما زال قريبًا. لا يستطيع الوصول إلينا هنا، <ffx:wonder>لكنه قد يصل عند الفخ.<ffx:neutral>')
a(1131,'يا رفاق! لا تستسلموا! هذا الدخيل أسوأ من قطاع الطرق! الجرحى والعزّل... لا يرحم أحدًا! رأيت ذلك بنفسي!')
a(1133,'أيها الدخيل! خذ ما تحتاج إليه وارحل! لا تقتل... لم نؤذِ صديقك... لقد ذهب إلى الكنيسة...')
a(1136,'<ffx:fear_strong>أنت... لا تقتل أحدًا! <ffx:fear>صديقك هرب... ولم نؤذِه...<ffx:neutral>')
a(1142,'<ffx:fear>وصديقك حي أيضًا... أطلقت أولغا سراحه، فذهب إلى الكنيسة...<ffx:neutral>')
a(1143,'<ffx:fear>لن أشي بك، لا تقلق... الحق به قبل أن يراك الآخرون... أرجوك...<ffx:neutral>')
a(1144,'<ffx:fear_strong>دخيل! النجدة! إنه هنا!<ffx:neutral>')
a(1145,'<ffx:fear_strong>إنه هنا! هنا، النجدة!<ffx:neutral>')
a(1146,'<ffx:fear_strong>أرجوك لا تطلق النار... لا تتعرض لنا، ولن نتعرض لك...<ffx:neutral>')
a(1149,'<ffx:anger>أحكم العقدة، وإلا انقطع الحبل!<ffx:neutral>')
a(1150,'<ffx:anger>مهلًا! هل أعلّمك كيف تجلس بلا عمل؟ <ffx:disgust>لا! فلا تتدخل في عملي!<ffx:neutral>')
a(1151,'<ffx:wonder_strong>أردت المساعدة فقط، فالحبل سينقطع حتمًا!<ffx:neutral>')
a(1153,'<ffx:wonder_strong>أجل، أخطأت! أأبقى جالسًا هنا بقية حياتي؟ <ffx:disgust_light>أضاع سدى كل ما أمضيته من وقت لأكسب تلك الشارات؟<ffx:neutral>')
a(1154,'<ffx:anger>سدى؟ طبعًا لا! <ffx:smile_light>حراستك هذا الدرب عمل مهم! <ffx:wonder>فذلك الرجل لم يأت وحده! <ffx:disgust_light>لماذا تظن أنني أنصب الفخاخ؟<ffx:neutral>')
a(1155,'<ffx:fear>هذا ما ظننته... فالمجلس لا <ffx:disgust_light>يجتمع إلا لأمر خطير... <ffx:wonder>بالمناسبة، هل نصبت فخًا عند مدخل المعسكر؟<ffx:neutral>')
a(1159,'<ffx:anger>ماذا تعني بقولك «أي كهف»؟ <ffx:anger_light>الكهف خلف البركة، أعلى الجدول! <ffx:wonder>إنه يؤدي مباشرة إلى المعسكر!<ffx:neutral>')
a(1160,'<ffx:anger>أعرف إلى أين يؤدي! لكنني <ffx:disgust>لم أصل إليه بعد! <ffx:wonder>سأنتهي هنا، ثم أصلح الفخاخ القديمة على الدرب، وأترك فخ الكهف للنهاية.<ffx:neutral>')
a(1161,'<ffx:smile_light>كما تشاء! لكن إن وصل الدخلاء إلى <ffx:wonder>المعسكر عبر الكهف، فستجف مؤخرتك من الجلوس على <ffx:smile_light>شرفة بيت المعلم أسبوعًا على الأقل!<ffx:neutral>')
a(1163,'<ffx:smile>كما يحلو لك، هاها!<ffx:neutral>')
a(1164,'<ffx:disgust>ذلك الوغد! يقضي <ffx:anger>النهار ينبش أنفه ويهذي... <ffx:disgust_strong>متعالم لعين!<ffx:neutral>')
a(1166,'<ffx:wonder>حسنًا! لا تنسَ الكهف فحسب!<ffx:neutral>')
a(1168,'<ffx:disgust>لقد تجاوز حده... الآن <ffx:anger>سأترك الكهف لآخر شيء حتمًا...<ffx:neutral>')
a(1169,'<ffx:disgust>يا لسوء حظي، لقد انتبه إليّ القبطان! «لا بد من حرس شرف»...<ffx:neutral>')
a(1170,'<ffx:wonder>كان يمكنني مطاردة قطاع الطرق مع الآخرين، لكن <ffx:disgust>لا، عليّ الجلوس هنا كالفتيات...<spits><ffx:neutral>')
a(1177,'<ffx:anger_light>أنهيت دورية للتو وأستمتع الآن بوقت فراغي، فكفّ عن مضايقتي!<ffx:neutral>')
a(1178,'<ffx:disgust_light>وقت الفراغ للراحة، وستفقد <ffx:wonder>صوتك إن واصلت هكذا!<ffx:neutral>')
a(1179,'<ffx:wonder>وما شأنك أنت؟<ffx:neutral>')
a(1180,'<ffx:wonder>لا شأن لي، لا يهمني حتى لو أصبحت أبكم، <ffx:disgust>لكن هذا الشيء لن ينطق بكلمة على أي حال!<ffx:neutral>')
a(1184,'<ffx:anger>سترى! سيُذهل الجميع حين يتكلم!<ffx:neutral>')
a(1192,'<ffx:anger_strong>ما بك؟ «مرحبًا!»<ffx:neutral>')
a(1193,'<ffx:anger_strong>هيا أيها المسخ! «مرحبًا!»<ffx:neutral>')
a(1196,'<ffx:disgust>يا له من عنيد...<ffx:neutral>')
a(1198,'<ffx:wonder>ذلك الساشكا محظوظ حقًا... <ffx:anger_light>ضرب دخيلًا على رأسه، وها هو يدخل بيت المعلم سريعًا <ffx:disgust_light>ليؤدي القسم! لقد صار مدرّبًا!<ffx:neutral>')
a(1199,'<ffx:wonder_strong>لكنه استحق ذلك! <ffx:anger_light>كان الدخيل صعب المراس، رغم وجود ثلاثة من رجالنا حوله!<ffx:neutral>')
